create extension if not exists pgcrypto;
create type public.user_role as enum ('buyer','seller','admin');
create type public.drop_status as enum ('draft','live','locked','completed','cancelled');
create type public.commitment_status as enum ('pending','paid','qualified','converted','refunded','forfeited','cancelled');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, role public.user_role not null default 'buyer', full_name text, phone text, created_at timestamptz not null default now());
create table public.sellers(id uuid primary key default gen_random_uuid(), owner_id uuid references auth.users(id), business_name text not null, gstin text, status text not null default 'pending', created_at timestamptz not null default now());
create table public.products(id uuid primary key default gen_random_uuid(), brand text not null, name text not null, sku text unique, image_url text, reference_price numeric(12,2), active boolean not null default true, created_at timestamptz not null default now());
create table public.drops(id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id), slug text unique not null, status public.drop_status not null default 'draft', starts_at timestamptz, ends_at timestamptz, commitment_amount numeric(12,2) not null default 499, created_at timestamptz not null default now());
create table public.drop_tiers(id uuid primary key default gen_random_uuid(), drop_id uuid not null references public.drops(id) on delete cascade, buyer_threshold int not null check(buyer_threshold>0), price numeric(12,2) not null check(price>0), unique(drop_id,buyer_threshold));
create table public.commitments(id uuid primary key default gen_random_uuid(), drop_id uuid not null references public.drops(id), buyer_id uuid not null references auth.users(id), max_price numeric(12,2) not null, token_amount numeric(12,2) not null, status public.commitment_status not null default 'pending', payment_provider text, payment_ref text, created_at timestamptz not null default now(), unique(drop_id,buyer_id));
create table public.seller_offers(id uuid primary key default gen_random_uuid(), drop_id uuid not null references public.drops(id), seller_id uuid not null references public.sellers(id), unit_price numeric(12,2) not null, quantity int not null, valid_until timestamptz not null, status text not null default 'submitted', created_at timestamptz not null default now());
create table public.orders(id uuid primary key default gen_random_uuid(), commitment_id uuid unique not null references public.commitments(id), seller_offer_id uuid references public.seller_offers(id), final_price numeric(12,2) not null, balance_due numeric(12,2) not null, status text not null default 'pending_payment', created_at timestamptz not null default now());
alter table public.profiles enable row level security;alter table public.sellers enable row level security;alter table public.products enable row level security;alter table public.drops enable row level security;alter table public.drop_tiers enable row level security;alter table public.commitments enable row level security;alter table public.seller_offers enable row level security;alter table public.orders enable row level security;
create policy "public products" on public.products for select using(active=true);create policy "public live drops" on public.drops for select using(status='live');create policy "public tiers" on public.drop_tiers for select using(true);create policy "own profile" on public.profiles for select using(auth.uid()=id);create policy "own commitments" on public.commitments for select using(auth.uid()=buyer_id);create policy "create own commitments" on public.commitments for insert with check(auth.uid()=buyer_id);create policy "own orders" on public.orders for select using(exists(select 1 from public.commitments c where c.id=commitment_id and c.buyer_id=auth.uid()));
create index commitments_drop_status_idx on public.commitments(drop_id,status);create index offers_drop_idx on public.seller_offers(drop_id);